// get length of platforms[]
unsigned int platform_len(void)
{
    unsigned int c;

    for(c = 0; platforms[c].cstoolname; c++);

    return c;
}

// get platform entry encoded n (first byte for input data of OSS fuzz)
unsigned int get_platform_entry(uint8_t n)
{
    return n % platform_len();
}

// get cstoolname from encoded n (first byte for input data of OSS fuzz)
const char *get_platform_cstoolname(uint8_t n)
{
    return platforms[get_platform_entry(n)].cstoolname;
}

bool SystemZ_getInstruction(csh ud, const uint8_t *code, size_t code_len, MCInst *MI,
                uint16_t *size, uint64_t address, void *info)
{
        uint64_t Inst;
        const uint8_t *Table;
        uint16_t I;

        // The top 2 bits of the first byte specify the size.
        if (*code < 0x40) {
                *size = 2;
                Table = DecoderTable16;
        } else if (*code < 0xc0) {
                *size = 4;
                Table = DecoderTable32;
        } else {
                *size = 6;
                Table = DecoderTable48;
        }

        if (code_len < *size)
                // short of input data
                return false;

        if (MI->flat_insn->detail) {
                memset(MI->flat_insn->detail, 0, offsetof(cs_detail, sysz)+sizeof(cs_sysz));
        }

        // Construct the instruction.
        Inst = 0;
        for (I = 0; I < *size; ++I)
                Inst = (Inst << 8) | code[I];

        return decodeInstruction(Table, MI, Inst, address, info, 0);
}

